#pragma once

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <glm/glm.hpp>
#include <string>
#include <optional>

namespace ptv {

// Public symbol for downstream reference (do not register here)
class FlightSystemMechanic;

struct FlightParams {
    float cruise_max_speed_mps = 6.0f;
    float boost_multiplier = 1.6f;
    float accel_tau_s = 0.20f;
    float decel_tau_s = 0.25f;
    float altitude_rate_mps = 2.0f;
    bool  bank_assist = true;
    bool  comfort_vignette_on_boost = true;
    float oob_return_delay_s = 1.0f;
    float collision_soft_bounce_coeff = 0.35f;
    std::string no_fly_volumes_tag = "no_fly";
    float bounds_radius_m = 300.0f; // simple spherical OOB guard
};

enum class FlightMode : std::uint8_t { Hover = 0, Flight = 1, Returning = 2 };

struct FlightStateInternal {
    FlightMode mode = FlightMode::Hover;
    glm::vec3 velocity{0.0f};        // m/s
    glm::vec3 target_velocity{0.0f};
    bool boost_held = false;
    bool last_boost_held = false;
    bool brake_intent = false;

    // Out-of-bounds return
    bool oob_active = false;
    float oob_t = 0.0f;
    glm::vec3 last_safe_pos{0.0f, 1.7f, 0.0f};
    glm::vec3 oob_start_pos{0.0f};

    // Recent threat/evasion direction (world-space). If unknown, use +X (HMD right surrogate)
    glm::vec3 recent_incoming_dir{-1.0f, 0.0f, 0.0f};
};

// Combined per-frame inputs read from this entity's CMechanicBinding entry
struct FlightInputs {
    // Left stick thrust in XZ plane; y used iff caller supplies hover ascent/descend bias
    glm::vec2 left_stick{0.0f};
    bool left_stick_click = false;   // boost modifier when held
    float right_stick_vert = 0.0f;   // altitude assist scaler (-1..1)
    bool a_double_tap = false;       // toggle hover/flight or brake-to-hover
    bool b_tap = false;              // quick evade burst
    // Frame selection: "head" or "controller" (fallback head)
    std::string ref_frame = "head";

    // Optional stubs supplied by harness for testing
    bool in_no_fly = false;          // if true, deny entering flight
    bool debug_hit = false;          // if true, treat as soft collision this frame
    glm::vec3 debug_hit_normal{0.0f, 1.0f, 0.0f}; // world-space normal
};

// Helpers implemented in .cpp files
FlightParams fs_parse_params(const nlohmann::json& p);
FlightInputs fs_read_inputs_from_binding(World& w, std::uint32_t e, const std::string& my_mech_id);
void fs_publish_tag(World& w, std::uint32_t e, const std::string& tag);
void fs_publish_locomotion_velocity(World& w, std::uint32_t e, const glm::vec3& v);
void fs_publish_hover_enable(World& w, std::uint32_t e, bool on);
void fs_publish_aim_stabilizer(World& w, std::uint32_t e, bool enabled, float strength01);
void fs_publish_vignette(World& w, std::uint32_t e, float strength01);
void fs_publish_haptics(World& w, std::uint32_t e, const std::string& pattern_id, const std::string& hand, float amp, float dur_s);

// Physics & comfort steps
void fs_step_controls(const FlightParams& cfg, const FlightInputs& in, float dt, FlightStateInternal& st);
void fs_step_physics(const FlightParams& cfg, const FlightInputs& in, float dt, World& w, std::uint32_t e, FlightStateInternal& st);
void fs_step_comfort(const FlightParams& cfg, const FlightInputs& in, float dt, World& w, std::uint32_t e, FlightStateInternal& st);

// Small math helpers
inline float fs_exp_smooth(float current, float target, float tau_s, float dt) {
    if (tau_s <= 0.0f) return target;
    float a = 1.0f - std::exp(-dt / tau_s);
    return current + (target - current) * a;
}

inline glm::vec3 fs_exp_smooth_vec3(const glm::vec3& c, const glm::vec3& t, float tau_s, float dt) {
    return glm::vec3(
        fs_exp_smooth(c.x, t.x, tau_s, dt),
        fs_exp_smooth(c.y, t.y, tau_s, dt),
        fs_exp_smooth(c.z, t.z, tau_s, dt)
    );
}

} // namespace ptv

#include "flight_system_shared.h"

#include <algorithm>
#include <string>
#include <vector>

namespace ptv {

FlightParams fs_parse_params(const nlohmann::json& p) {
    FlightParams cfg;
    if (!p.is_object()) return cfg;
    cfg.cruise_max_speed_mps = p.value("cruise_max_speed_mps", cfg.cruise_max_speed_mps);
    cfg.boost_multiplier     = p.value("boost_multiplier", cfg.boost_multiplier);
    cfg.accel_tau_s          = p.value("accel_tau_s", cfg.accel_tau_s);
    cfg.decel_tau_s          = p.value("decel_tau_s", cfg.decel_tau_s);
    cfg.altitude_rate_mps    = p.value("altitude_rate_mps", cfg.altitude_rate_mps);
    cfg.bank_assist          = p.value("bank_assist", cfg.bank_assist);
    cfg.comfort_vignette_on_boost = p.value("comfort_vignette_on_boost", cfg.comfort_vignette_on_boost);
    cfg.oob_return_delay_s   = p.value("oob_return_delay_s", cfg.oob_return_delay_s);
    cfg.collision_soft_bounce_coeff = p.value("collision_soft_bounce_coeff", cfg.collision_soft_bounce_coeff);
    cfg.no_fly_volumes_tag   = p.value("no_fly_volumes_tag", cfg.no_fly_volumes_tag);
    cfg.bounds_radius_m      = p.value("bounds_radius_m", cfg.bounds_radius_m);
    return cfg;
}

static std::optional<nlohmann::json> fs_find_own_params_json(World& w, std::uint32_t e, const std::string& my_mech_id) {
    if (!w.has<CMechanicBinding>(e)) return std::nullopt;
    auto& entries = w.get<CMechanicBinding>(e).entries;
    for (const auto& entry : entries) {
        if (entry.id == my_mech_id || entry.builtin_id == my_mech_id) {
            auto j = nlohmann::json::parse(entry.params_json, nullptr, /*allow_exceptions=*/false);
            if (j.is_object()) return j;
        }
    }
    return std::nullopt;
}

FlightInputs fs_read_inputs_from_binding(World& w, std::uint32_t e, const std::string& my_mech_id) {
    FlightInputs in;
    auto jp = fs_find_own_params_json(w, e, my_mech_id);
    if (!jp.has_value()) return in;
    const auto& j = *jp;

    // Left stick
    if (j.contains("l_stick_x") && j.contains("l_stick_y")) {
        in.left_stick.x = j.value("l_stick_x", 0.0f);
        in.left_stick.y = j.value("l_stick_y", 0.0f);
    }
    in.left_stick_click = j.value("l_click_held", false);

    // Right vertical
    in.right_stick_vert = j.value("r_vert", 0.0f);

    // Buttons
    in.a_double_tap = j.value("a_double_tap", false);
    in.b_tap = j.value("b_tap", false);

    // Frame & stubs
    in.ref_frame = j.value("frame", std::string("head"));
    in.in_no_fly = j.value("in_no_fly", false);

    if (j.contains("debug_hit") && j.value("debug_hit", false)) {
        in.debug_hit = true;
        if (j.contains("debug_hit_normal") && j["debug_hit_normal"].is_array() && j["debug_hit_normal"].size() == 3) {
            in.debug_hit_normal.x = j["debug_hit_normal"][0].get<float>();
            in.debug_hit_normal.y = j["debug_hit_normal"][1].get<float>();
            in.debug_hit_normal.z = j["debug_hit_normal"][2].get<float>();
        }
    }

    return in;
}

void fs_step_controls(const FlightParams& cfg, const FlightInputs& in, float dt, FlightStateInternal& st) {
    (void)cfg; (void)dt;

    // Toggle/Brake handling is decided in physics step with access to transform; here mark intents
    st.boost_held = in.left_stick_click;

    // Compute target velocity in a simple world-aligned frame (XZ from left stick);
    // reference frame selection stub: if controller-relative was required, another system would rotate this
    // vector. Here we keep it world-aligned for stability (head/controller-relative resolved upstream).
    glm::vec3 target{in.left_stick.x, 0.0f, in.left_stick.y};

    float speed = glm::length(glm::vec2(target.x, target.z));
    if (speed > 1e-5f) target = glm::normalize(target);

    float max_spd = cfg.cruise_max_speed_mps * (st.boost_held ? cfg.boost_multiplier : 1.0f);

    target *= max_spd;

    // Altitude assist via right stick vertical
    target.y += cfg.altitude_rate_mps * std::clamp(in.right_stick_vert, -1.0f, 1.0f);

    st.target_velocity = target;

    // Quick evade: lateral impulse to +X if unknown; nudge instantaneous velocity
    if (in.b_tap) {
        glm::vec3 lateral{1.0f, 0.0f, 0.0f};
        // If we had a recent incoming dir (towards us), push opposite that projected on XZ
        glm::vec3 inc = st.recent_incoming_dir;
        inc.y = 0.0f;
        if (glm::length2(inc) > 1e-4f) {
            lateral = -glm::normalize(inc);
        }
        st.velocity += lateral * 3.0f; // small burst
    }
}

} // namespace ptv

#include "flight_system_shared.h"

#include <algorithm>
#include <cmath>

namespace ptv {

static glm::vec3 fs_get_position(const World& w, std::uint32_t e) {
    if (!w.has<CTransform>(e)) return glm::vec3(0.0f, 1.7f, 0.0f);
    const auto& tr = w.get<CTransform>(e).t;
    return glm::vec3(tr.position.x, tr.position.y, tr.position.z);
}

static void fs_set_position(World& w, std::uint32_t e, const glm::vec3& p) {
    if (!w.has<CTransform>(e)) return;
    auto& tr = w.get<CTransform>(e).t;
    tr.position.x = p.x; tr.position.y = p.y; tr.position.z = p.z;
}

static void fs_apply_soft_collision(const FlightParams& cfg, const FlightInputs& in, FlightStateInternal& st) {
    if (!in.debug_hit) return; // stubbed; real cast would go here
    glm::vec3 n = in.debug_hit_normal;
    float nlen2 = glm::length2(n);
    if (nlen2 < 1e-6f) return;
    n = glm::normalize(n);
    float vn = glm::dot(st.velocity, n);
    if (vn < 0.0f) {
        // Reflect and dampen using soft bounce coeff
        st.velocity = st.velocity - (1.0f + cfg.collision_soft_bounce_coeff) * vn * n;
    }
}

static void fs_check_oob_and_handle(const FlightParams& cfg, float dt, World& w, std::uint32_t e, FlightStateInternal& st) {
    glm::vec3 p = fs_get_position(w, e);

    if (st.mode != FlightMode::Returning) {
        float r = glm::length(p);
        if (r <= cfg.bounds_radius_m * 0.98f) {
            st.last_safe_pos = p; // update safe pos while comfortably inside
        }
        if (r > cfg.bounds_radius_m) {
            // Start auto-return
            st.mode = FlightMode::Returning;
            st.oob_active = true;
            st.oob_t = 0.0f;
            st.oob_start_pos = p;
            st.velocity = glm::vec3(0.0f);
            // HUD warning tag (consumed by HUD if present)
            fs_publish_tag(w, e, std::string("hud.warn:{\"text\":\"Returning to bounds...\",\"severity\":\"info\"}"));
            // Immediately advertise hover intent so other systems can prep stabilization
            fs_publish_hover_enable(w, e, true);
        }
    }

    if (st.mode == FlightMode::Returning) {
        st.oob_t += dt;
        float t = std::clamp(st.oob_t / std::max(0.001f, cfg.oob_return_delay_s), 0.0f, 1.0f);
        glm::vec3 pnew = glm::mix(st.oob_start_pos, st.last_safe_pos, t);
        fs_set_position(w, e, pnew);
        fs_publish_locomotion_velocity(w, e, glm::vec3(0.0f));
        if (t >= 1.0f) {
            st.mode = FlightMode::Hover;
            st.oob_active = false;
            // Land in hover with zero velocity
            fs_publish_hover_enable(w, e, true);
        }
    }
}

void fs_step_physics(const FlightParams& cfg, const FlightInputs& in, float dt, World& w, std::uint32_t e, FlightStateInternal& st) {
    // Check OOB return first; if active, override motion
    fs_check_oob_and_handle(cfg, dt, w, e, st);
    if (st.mode == FlightMode::Returning) return;

    // Enter/exit flight via A double-tap (deny enter if in no-fly)
    if (in.a_double_tap) {
        if (st.mode == FlightMode::Flight) {
            // Brake to hover immediately
            st.mode = FlightMode::Hover;
            st.velocity = glm::vec3(0.0f);
            fs_publish_locomotion_velocity(w, e, st.velocity);
            fs_publish_hover_enable(w, e, true);
        } else if (!in.in_no_fly) {
            st.mode = FlightMode::Flight;
            fs_publish_hover_enable(w, e, false);
        }
    }

    // In hover, allow gentle altitude nudge but keep zeroed velocity output
    if (st.mode == FlightMode::Hover) {
        glm::vec3 p = fs_get_position(w, e);
        p.y += cfg.altitude_rate_mps * std::clamp(in.right_stick_vert, -1.0f, 1.0f) * dt;
        fs_set_position(w, e, p);
        fs_publish_locomotion_velocity(w, e, glm::vec3(0.0f));
        return;
    }

    // Flight mode motion
    // Smooth towards target velocity with accel/decel taus (per-axis)
    auto choose_tau = [&](float cur, float tgt){ return (std::fabs(tgt) > std::fabs(cur)) ? cfg.accel_tau_s : cfg.decel_tau_s; };
    glm::vec3 vel = st.velocity;
    glm::vec3 tgt = st.target_velocity;

    float tau_x = choose_tau(vel.x, tgt.x);
    float tau_y = choose_tau(vel.y, tgt.y);
    float tau_z = choose_tau(vel.z, tgt.z);

    vel.x = fs_exp_smooth(vel.x, tgt.x, tau_x, dt);
    vel.y = fs_exp_smooth(vel.y, tgt.y, tau_y, dt);
    vel.z = fs_exp_smooth(vel.z, tgt.z, tau_z, dt);

    st.velocity = vel;

    // Optional soft collision avoidance/bounce
    fs_apply_soft_collision(cfg, in, st);

    // Integrate position
    glm::vec3 p = fs_get_position(w, e);
    p += st.velocity * dt;
    fs_set_position(w, e, p);

    // Publish current velocity for interop
    fs_publish_locomotion_velocity(w, e, st.velocity);

    // Haptics on boost engage
    if (st.boost_held && !st.last_boost_held) {
        fs_publish_haptics(w, e, "flight_boost", "both", 1.0f, 0.12f);
    }
    st.last_boost_held = st.boost_held;

    // Quick-evade haptics
    if (in.b_tap) {
        fs_publish_haptics(w, e, "evade_burst", "both", 1.0f, 0.08f);
    }
}

} // namespace ptv

#include "flight_system_shared.h"

#include <algorithm>
#include <cmath>

namespace ptv {

void fs_publish_tag(World& w, std::uint32_t e, const std::string& tag) {
    if (w.has<CTag>(e)) {
        auto& t = w.get<CTag>(e).tags;
        t.emplace_back(tag);
    } else {
        CTag t; t.tags.emplace_back(tag);
        w.emplace_or_replace<CTag>(e, t);
    }
}

void fs_publish_locomotion_velocity(World& w, std::uint32_t e, const glm::vec3& v) {
    nlohmann::json j = {
        {"vx", v.x}, {"vy", v.y}, {"vz", v.z}
    };
    fs_publish_tag(w, e, std::string("locomotion.velocity:") + j.dump());
}

void fs_publish_hover_enable(World& w, std::uint32_t e, bool on) {
    nlohmann::json j = {{"state", on ? "hover" : "off"}};
    fs_publish_tag(w, e, std::string("locomotion.mode:") + j.dump());
}

void fs_publish_aim_stabilizer(World& w, std::uint32_t e, bool enabled, float strength01) {
    nlohmann::json j = {{"enabled", enabled}, {"strength", std::clamp(strength01, 0.0f, 1.0f)}};
    fs_publish_tag(w, e, std::string("aim.stabilizer:") + j.dump());
}

void fs_publish_vignette(World& w, std::uint32_t e, float strength01) {
    // Ground sprint overlay revealed a comfort.vignette:* tag namespace. Use the same prefix.
    nlohmann::json j = {{"strength", std::clamp(strength01, 0.0f, 1.0f)}};
    fs_publish_tag(w, e, std::string("comfort.vignette:") + j.dump());
}

void fs_publish_haptics(World& w, std::uint32_t e, const std::string& pattern_id, const std::string& hand, float amp, float dur_s) {
    // From dependency: publish via prefix haptics.publish:
    nlohmann::json j = {{"pattern_id", pattern_id}, {"hand", hand}, {"intensity_scale", amp}, {"duration_s", dur_s}};
    fs_publish_tag(w, e, std::string("haptics.publish:") + j.dump());
}

void fs_step_comfort(const FlightParams& cfg, const FlightInputs& in, float dt, World& w, std::uint32_t e, FlightStateInternal& st) {
    (void)dt; (void)in;

    // Stabilized horizon (no camera roll). We can't control camera roll directly, but enable an aim stabilizer.
    // Scale with speed for mild stabilization while in flight; off in hover.
    if (st.mode == FlightMode::Flight) {
        float spd = glm::length(st.velocity);
        float k = std::clamp(spd / (cfg.cruise_max_speed_mps * cfg.boost_multiplier), 0.0f, 1.0f);
        fs_publish_aim_stabilizer(w, e, true, 0.2f + 0.5f * k);
        if (cfg.comfort_vignette_on_boost && st.boost_held) {
            fs_publish_vignette(w, e, 0.35f * k);
        } else {
            // Small baseline vignette at higher speeds for comfort
            fs_publish_vignette(w, e, 0.18f * k);
        }
    } else {
        fs_publish_aim_stabilizer(w, e, false, 0.0f);
        fs_publish_vignette(w, e, 0.0f);
    }
}

} // namespace ptv

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"

#include <nlohmann/json.hpp>
#include <glm/glm.hpp>

#include <string>
#include <algorithm>

#include "flight_system_shared.h"

namespace ptv {

class FlightSystemMechanic : public IMechanic {
public:
    void on_attach(World& w, std::uint32_t e, const nlohmann::json& params) override {
        (void)w; (void)e;
        cfg_ = fs_parse_params(params);
        st_ = FlightStateInternal{};
        // Start in Hover by default
        st_.mode = FlightMode::Hover;
    }

    void on_update(World& w, std::uint32_t e, float dt) override {
        if (!w.valid(e)) return;

        // Read inputs from this entity's binding entry each frame
        FlightInputs in = fs_read_inputs_from_binding(w, e, id());

        // Controls: compute target velocity & state intents
        fs_step_controls(cfg_, in, dt, st_);

        // Physics: integrate, handle OOB, collisions, enter/exit flight & hover
        fs_step_physics(cfg_, in, dt, w, e, st_);

        // Comfort & interop tags (stabilizer, vignette)
        fs_step_comfort(cfg_, in, dt, w, e, st_);
    }

    void on_detach(World& w, std::uint32_t e) override {
        // Ensure we leave with hover stable and comfort reset
        fs_publish_hover_enable(w, e, true);
        fs_publish_locomotion_velocity(w, e, glm::vec3(0.0f));
        fs_publish_aim_stabilizer(w, e, false, 0.0f);
        fs_publish_vignette(w, e, 0.0f);
    }

    std::string id() const override { return "generated.flight_system"; }

private:
    FlightParams cfg_{};
    FlightStateInternal st_{};
};

} // namespace ptv

PTV_REGISTER_MECHANIC("generated.flight_system", ptv::FlightSystemMechanic)
